(6869915, 1034937, 96664, '<td valign="top">Probably my favorite from the challenge. Should win in my opinion. Well done.</td>', 'Probably my favorite from the challenge. Should win in my opinion. Well done.', '2012-09-26 12:34:44.000000', NULL, 1),
(6869916, 1034985, 118154, '<td valign="top">Top ten in my opinion.</td>', 'Top ten in my opinion.', '2012-09-26 12:34:47.000000', NULL, 1),
(6869990, 1034765, 52267, '<td valign="top">Great idea, and nicely executed. I love that fact that the small chain is in a bow. That is what "sells" the shot imo. Also a great contrast in materials. I don''t think the shot would have worked as well had the big chains not been rusted. Well done.</td>', 'Great idea, and nicely executed. I love that fact that the small chain is in a bow. That is what "sells" the shot imo. Also a great contrast in materials. I don''t think the shot would have worked as well had the big chains not been rusted. Well done.', '2012-09-26 16:27:02.000000', NULL, 1),
(6869991, 1034944, 52267, '<td valign="top">Very interesting image and nice job on the crop. The cropping on this makes the image for me.</td>', 'Very interesting image and nice job on the crop. The cropping on this makes the image for me.', '2012-09-26 16:29:22.000000', NULL, 1),
(6869993, 1034680, 52267, '<td valign="top">Nice photo. I may have liked to see more of the mixer on the left side, but I understand what you were going for and it is nicely done.</td>', 'Nice photo. I may have liked to see more of the mixer on the left side, but I understand what you were going for and it is nicely done.', '2012-09-26 16:31:09.000000', NULL, 1),
(6869994, 1034892, 52267, '<td valign="top">Nice idea. I would have like to see the face of the clock sharper to contrast the movement of the beater, but none-the-less it is well done.</td>', 'Nice idea. I would have like to see the face of the clock sharper to contrast the movement of the beater, but none-the-less it is well done.', '2012-09-26 16:32:36.000000', NULL, 1),
(6869998, 1034519, 52267, '<td valign="top">Nice use of the sepia tone to make the image feel more antique. Nice job.</td>', 'Nice use of the sepia tone to make the image feel more antique. Nice job.', '2012-09-26 16:36:52.000000', NULL, 1),
(6870008, 1034966, 117037, '<td valign="top">Lovely composition 10!</td>', 'Lovely composition 10!', '2012-09-26 17:06:26.000000', NULL, 1),
